head.script:
scwin.init = function() {
    var jsonData = [{
        "col1": "1",
        "col2": "2",
        "col3": "3",
        "col4": "4"
    }];
    dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
    grd.setColumnOrder(["col2", "col1"]);
};
scwin.trigger2_onclick = function(e) {
    grd.setColumnOrder(["col1", "col2"]);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 2, 1 버튼을 클릭한다.
    //1. In the browser, click the 2, 1 button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    //Verify step 1. col2 ('2') 과 col1 ('1') 로 변경된다.
    //1. It is changed to col2 ('2') and col1 ('1').
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th:first').text() == 'name2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th:last').text() == 'name1'", "true");
    //Test step 2. 1, 2 버튼을 클릭한다.
    //2. Click the 1, 2 button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    //Verify step 2. col1 ('1') 과 col2 ('2') 로 변경된다.
    //2. Change to col1 ('1') and col2 ('2').
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th:first').text() == 'name1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th:last').text() == 'name2'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 30-Jan-2018        
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
